

DROP TABLE IF EXISTS archivedtexts;
CREATE TABLE `archivedtexts` (
  `AtID` int unsigned NOT NULL AUTO_INCREMENT,
  `AtLgID` int unsigned NOT NULL,
  `AtTitle` varchar(200) NOT NULL,
  `AtText` text NOT NULL,
  `AtAnnotatedText` longtext NOT NULL,
  `AtAudioURI` varchar(200) DEFAULT NULL,
  `AtSourceURI` varchar(1000) DEFAULT NULL,
  PRIMARY KEY (`AtID`),
  KEY `AtLgID` (`AtLgID`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;

DROP TABLE IF EXISTS archtexttags;
CREATE TABLE `archtexttags` (   `AgAtID` int unsigned NOT NULL,   `AgT2ID` int unsigned NOT NULL,   PRIMARY KEY (`AgAtID`,`AgT2ID`),   KEY `AgAtID` (`AgAtID`),   KEY `AgT2ID` (`AgT2ID`) ) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DROP TABLE IF EXISTS languages;
CREATE TABLE `languages` (   `LgID` int unsigned NOT NULL AUTO_INCREMENT,   `LgName` varchar(40) NOT NULL,   `LgDict1URI` varchar(200) NOT NULL,   `LgDict2URI` varchar(200) DEFAULT NULL,   `LgGoogleTranslateURI` varchar(200) DEFAULT NULL,   `LgExportTemplate` varchar(1000) DEFAULT NULL,   `LgTextSize` int unsigned NOT NULL DEFAULT '100',   `LgCharacterSubstitutions` varchar(500) NOT NULL,   `LgRegexpSplitSentences` varchar(500) NOT NULL,   `LgExceptionsSplitSentences` varchar(500) NOT NULL,   `LgRegexpWordCharacters` varchar(500) NOT NULL,   `LgRemoveSpaces` int unsigned NOT NULL DEFAULT '0',   `LgSplitEachChar` int unsigned NOT NULL DEFAULT '0',   `LgRightToLeft` int unsigned NOT NULL DEFAULT '0',   PRIMARY KEY (`LgID`),   UNIQUE KEY `LgName` (`LgName`) ) ENGINE=MyISAM AUTO_INCREMENT=4 DEFAULT CHARSET=utf8;
