DROP TABLE IF EXISTS sentences;
CREATE TABLE `sentences` (   `SeID` int unsigned NOT NULL AUTO_INCREMENT,   `SeLgID` int unsigned NOT NULL,   `SeTxID` int unsigned NOT NULL,   `SeOrder` int unsigned NOT NULL,   `SeText` text,   PRIMARY KEY (`SeID`),   KEY `SeLgID` (`SeLgID`),   KEY `SeTxID` (`SeTxID`),   KEY `SeOrder` (`SeOrder`) ) ENGINE=MyISAM AUTO_INCREMENT=870 DEFAULT CHARSET=utf8;

DROP TABLE IF EXISTS settings;
CREATE TABLE `settings` (   `StKey` varchar(40) NOT NULL,   `StValue` varchar(40) DEFAULT NULL,   PRIMARY KEY (`StKey`) ) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DROP TABLE IF EXISTS tags;
CREATE TABLE `tags` (   `TgID` int unsigned NOT NULL AUTO_INCREMENT,   `TgText` varchar(20) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,   `TgComment` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',   PRIMARY KEY (`TgID`),   UNIQUE KEY `TgText` (`TgText`) ) ENGINE=MyISAM AUTO_INCREMENT=407 DEFAULT CHARSET=utf8;

DROP TABLE IF EXISTS tags2;
CREATE TABLE `tags2` (   `T2ID` int unsigned NOT NULL AUTO_INCREMENT,   `T2Text` varchar(20) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,   `T2Comment` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',   PRIMARY KEY (`T2ID`),   UNIQUE KEY `T2Text` (`T2Text`) ) ENGINE=MyISAM AUTO_INCREMENT=5 DEFAULT CHARSET=utf8;

DROP TABLE IF EXISTS textitems;
CREATE TABLE `textitems` (   `TiID` int unsigned NOT NULL AUTO_INCREMENT,   `TiLgID` int unsigned NOT NULL,   `TiTxID` int unsigned NOT NULL,   `TiSeID` int unsigned NOT NULL,   `TiOrder` int unsigned NOT NULL,   `TiWordCount` int unsigned NOT NULL,   `TiText` varchar(250) NOT NULL,   `TiTextLC` varchar(250) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,   `TiIsNotWord` tinyint(1) NOT NULL,   PRIMARY KEY (`TiID`),   KEY `TiLgID` (`TiLgID`),   KEY `TiTxID` (`TiTxID`),   KEY `TiSeID` (`TiSeID`),   KEY `TiOrder` (`TiOrder`),   KEY `TiTextLC` (`TiTextLC`),   KEY `TiIsNotWord` (`TiIsNotWord`) ) ENGINE=MyISAM AUTO_INCREMENT=9114 DEFAULT CHARSET=utf8;

DROP TABLE IF EXISTS texts;
CREATE TABLE `texts` (   `TxID` int unsigned NOT NULL AUTO_INCREMENT,   `TxLgID` int unsigned NOT NULL,   `TxTitle` varchar(200) NOT NULL,   `TxText` text NOT NULL,   `TxAnnotatedText` longtext NOT NULL,   `TxAudioURI` varchar(200) DEFAULT NULL,   `TxSourceURI` varchar(1000) DEFAULT NULL,   PRIMARY KEY (`TxID`),   KEY `TxLgID` (`TxLgID`) ) ENGINE=MyISAM AUTO_INCREMENT=15 DEFAULT CHARSET=utf8;

DROP TABLE IF EXISTS texttags;
CREATE TABLE `texttags` (   `TtTxID` int unsigned NOT NULL,   `TtT2ID` int unsigned NOT NULL,   PRIMARY KEY (`TtTxID`,`TtT2ID`),   KEY `TtTxID` (`TtTxID`),   KEY `TtT2ID` (`TtT2ID`) ) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DROP TABLE IF EXISTS words;
CREATE TABLE `words` (   `WoID` int unsigned NOT NULL AUTO_INCREMENT,   `WoLgID` int unsigned NOT NULL,   `WoText` varchar(250) NOT NULL,   `WoTextLC` varchar(250) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,   `WoStatus` tinyint NOT NULL,   `WoTranslation` varchar(500) NOT NULL DEFAULT '*',   `WoRomanization` varchar(100) DEFAULT NULL,   `WoSentence` varchar(1000) DEFAULT NULL,   `WoCreated` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,   `WoStatusChanged` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',   `WoTodayScore` double NOT NULL DEFAULT '0',   `WoTomorrowScore` double NOT NULL DEFAULT '0',   `WoRandom` double NOT NULL DEFAULT '0',   PRIMARY KEY (`WoID`),   UNIQUE KEY `WoLgIDTextLC` (`WoLgID`,`WoTextLC`),   KEY `WoLgID` (`WoLgID`),   KEY `WoStatus` (`WoStatus`),   KEY `WoTextLC` (`WoTextLC`),   KEY `WoTranslation` (`WoTranslation`(333)),   KEY `WoCreated` (`WoCreated`),   KEY `WoStatusChanged` (`WoStatusChanged`),   KEY `WoTodayScore` (`WoTodayScore`),   KEY `WoTomorrowScore` (`WoTomorrowScore`),   KEY `WoRandom` (`WoRandom`) ) ENGINE=MyISAM AUTO_INCREMENT=1772 DEFAULT CHARSET=utf8;

DROP TABLE IF EXISTS wordtags;
CREATE TABLE `wordtags` (   `WtWoID` int unsigned NOT NULL,   `WtTgID` int unsigned NOT NULL,   PRIMARY KEY (`WtWoID`,`WtTgID`),   KEY `WtTgID` (`WtTgID`),   KEY `WtWoID` (`WtWoID`) ) ENGINE=MyISAM DEFAULT CHARSET=utf8;
