INSERT INTO texts VALUES('8','1','faire des affaires tout de suite en russe p94 13','13 LES LIVRAISONS\n13 ДОСТАВКИ/ ПОСТАВКИ\n1 Nous assurons les livraisons à domicile 24 heures sur 24.\n1 Мы обеспечиваем круглосуточную доставку на дом.\n2 Les livraisons de pétrole vers les raffineries ont diminué.\n2 Поставки нефти на нефтеперерабатывающие заволы сократились.\n3 Notre compagnie est heureuse de vous offrir un service de courrier express.\n3 Наша компания рада Вам предоставить сервис по экспресс-доставке почты.\n4 On propose des conditions de livraison FOB port Sud ou Saint-Pétersbourg,\n4 Предлагаются условия поставки ФОБ порт Южный или Санкт-Петербург.\n5 Nous pouvons livrer les marchandises dans n’importe quelle région.\n5 Мы можем доставлять товары в любые регионы.\n6 Notre magasin effectue la livraison des livres à l’étranger.\n6 Наш магазин осуществляет доставку книг за границу.\n7 Après la livraison de la marchandise à bord du navire, tous les\nrisques de détérioration incombent à l’acheteur.\n7 После доставки товара на борт судна все риски повреждения переходят на покупателя,\n8 Les frais de livraison sont inclus dans le prix d’achat.\n8 Расходы на доставку включаются в покупную стоимость.\n9 Pour un achat d\'un montant de plus de 30000 roubles, [а\nlivraison est gratuite.\n9 При покупке на сумму свыше 3о тыс. руб. - доставка бесплатная.\n10 La livraison est retardée d’une heure.\n10 Доставка отсрочивается на час.\n11 Pour le transport des matières dangereuses, il est indispensable d’ajouter 24 heures au délai de livraison.\n11 При перевозке опасных грузов к сроку доставки необходимо добавить одни сутки.\n12 Une tentative de livraison de drogue à la prison vient d’avorter.\n12 Пресечена попытка доставки наркотиков в тюрьму.','',NULL,NULL);
INSERT INTO texts VALUES('9','1','faire des affaires en russes tout de suite Au telephone p76 10','10 AU TÉLÉPHONE\n10 ПО ТЕЛЕФОНУ\n1 Pouvez-vous me donner le numéro de votre carte de crédit ?\n1 Moxere AH вы мне дать номер вашей кредитной карты?\n2 A quel numéro de téléphone peut-on vous appeler ?\n2 По какому телефону можно вам позвонить?\n3 Pouvez-vous nous rappeler demain ou après-demain ?\n3 Можете ли вы нам позвонить завтра или послезавтра?\n4 Je vous rappelle dès que j\'aurai la réponse.\n4 Явам позвоню как только получу ответ.\n5 Pouvez-vous épeler votre nom ?\n5 Продиктуйте по буквам вашу фамилию.\n6 Ne coupez pas, s’il vous plaît ! Ne raccrochez pas!\n6 Не отсоединяйтесь, пожалуйста! Не кладите трубку!\n7 Est-ce vous qui avez appelé ce matin ?\n7 Это вы звонили сегодня утром?\n8 Oui, je n\'ai pas pu vous joindre hier, votre portable était éteint.\n8 Да, вчера я не смогла дозвониться — ваш мобильник находился в режиме ожидания.\n9 Attendez, s’il vous plaît, que la communication soit établie.\n9 Пожалуйста, дождитесь подключения.\n10 Téléphonez-moi sur mon fixe.\n10 Позвоните мне на домашний телефон.\n11 C\'est vous sans doute qui avez eu un de mes collègues au téléphone?\n11 Должно быть вы говорили с кем-то из моих коллег ?\n12 Pourriez-vous me passer Madame Sidorova ?\n12 Будьте добры, позовите к телефону госпожу Сидорову.\n13 Peut-on lui laisser un message ?13 Что-нибудь ей передать?\n13 Что-нибудь ей передать?','',NULL,NULL);
INSERT INTO texts VALUES('10','1','faire des affaires en russe tout de suite Au telephone p78 10','10 AU TÉLÉPHONE\n10 ПО ТЕЛЕФОНУ\n14 Vous vous êtes trompé de numéro. Vous n’êtes pas au bon endroit.\n14 Вы ошиблись номером. Вы не туда попали.\n15 Pouvons-nous fixer un rendez-vous ?\n15 Можем мы назначить встречу?\n16 Dites-moi le jour et l’heure qui vous arrangent le mieux.\n16 Скажите, в какой день и в какое время вам удобнее.\n17 Appelez nos clients pour les informer que leur commande est bien arrivée.\n17 Обзванивайте клиентов о поступлении ожидаемого ими товара,\n18 Je vais vous indiquer notre agence la plus proche.\n18 Я вам назову наше ближайшее агентство.\n19 Je vous ai laissé, il y a trois jours, un message sur votre répondeur.\n19 Три дня назад я оставлял вам сообщение на\nавтоответчике.\n20 Pourriez-vous m\'accorder quelques minutes ?\n20 Могли бы вы уделить мне несколько минут?\n21 Appelez-le (la) directement.\n21 Позвоните ему / ей напрямую.\n22 Si j\'ai bonne mémoire, nous nous sommes déjà rencontrés à ce sujet.\n22 Если память мне не изменяет, мы с вами уже встречались по этому поводу.\n23 J\'ai bien reçu votre message. Ne vous inquiétez pas, je me souviens très bien.\n23 Я получил ваше сообщение. Не беспокойтесь, я хорошо помню...\n24 D\'où m\'appelez-vous. ? Où vous trouvez-vous en ce moment?\n24 Откуда вы звоните ? Где вы сейчас?','',NULL,'https://olivier.myeu.cloud/index.php/s/ps62b6wX4EpoFpf');
INSERT INTO texts VALUES('11','1','отреагировать «эмоционально умным» способом','Чтобы отреагировать «эмоционально умным» способом, нужно осознать, что произошло, принять своё переживание и направить энергию на то, на что можешь повлиять. Кроме того, развитые социально-эмоциональные навыки позволяют успешно выстраивать отношения с окружающими.','',NULL,'https://hh.kz/article/30064');
